node --input-type=module -e '
import { readFileSync } from "fs";
const lock = JSON.parse(readFileSync("/root/package-lock.json", "utf8"));
const pkgs = {};
for (const [path, info] of Object.entries(lock.packages || {})) {
  if (path === "" || !info.version) continue;
  const name = path.replace(/^node_modules\//, "");
  pkgs[name] = info.version;
}
const sorted = Object.entries(pkgs).sort();
for (const [name, ver] of sorted) {
  console.log(name + "@" + ver);
}
process.stderr.write("Total: " + sorted.length + "\n");
' > /root/all_packages.txt 2>/tmp/pkg_count.txt
cat /tmp/pkg_count.txt
wc -l /root/all_packages.txt

